class NpcVocalTicTests(unittest.TestCase):
 def test_four_source_locked_draft_entries(self):
  self.assertEqual(len(EXPECTED),4)
  for x in EXPECTED:
   self.assertEqual(next(e for e in L(x['plan'])['entries'] if e['id']==x['entry']['id']),x['entry'])
   self.assertEqual(L(x['plan'].replace('.json','.review.json'))['status'],'draft')
 def test_all_twentyfive_shared_tics_and_workflow_references(self):
  self.assertEqual(len(ANCHORS),25)
  for a in ANCHORS:
   e=next(e for e in L(a['plan'])['entries'] if e['id']==a['id']);self.assertEqual(e['source_sha256'],a['source_sha256']);self.assertEqual(hashlib.sha256(e['translation'].encode()).hexdigest(),a['translation_sha256']);self.assertIn('嘻嘻呵',e['translation']);self.assertNotIn('嘻嘻哟',e['translation'])
  for b in L('locales/zh-Hans/translation-workflow.json')['batches']:
   if b['plan']['path'] in {e['plan'] for e in EXPECTED}:
    for ref in b.values():self.assertEqual(hashlib.sha256((R/ref['path']).read_bytes()).hexdigest(),ref['sha256'])
if __name__=='__main__':unittest.main()
